// Blink: count clock cycles and flip LD0 every half period.
module top #(
  parameter CLK_HZ   = 100_000_000,  // the board clock: cycles per second
  parameter BLINK_HZ = 2
) (
  input             clk,             // W5
  output reg [15:0] led
);
  // Clock cycles in half a blink.
  localparam HALF = CLK_HZ / (2 * BLINK_HZ);

  reg [31:0] count = 0;
  initial led = 16'b0;

  always @(posedge clk) begin
    if (count == HALF - 1) begin
      count  <= 0;
      led[0] <= ~led[0];                                  // flip LD0
      if (led[0]) led[15:12] <= led[15:12] + 1;           // LD0 is about to go off: one more blink
    end else begin
      count <= count + 1;
    end
  end
endmodule
